fn shell_game(n: i32, x: i8) -> i8 {
    // Since the sequence of swaps repeats every 6 moves,
    // we only need to perform the first n % 6 moves.
    let r = (n as u32) % 6;
    let mut pos = x;

    // Simulate moves 1..=r
    // odd i:  swap positions 0 <-> 1
    // even i: swap positions 1 <-> 2
    for i in 1..=r {
        if i % 2 == 1 {
            // odd move: swap 0 <-> 1
            if pos == 0 {
                pos = 1;
            } else if pos == 1 {
                pos = 0;
            }
        } else {
            // even move: swap 1 <-> 2
            if pos == 1 {
                pos = 2;
            } else if pos == 2 {
                pos = 1;
            }
        }
    }

    pos
}

